mapper.update:
update notify_outbox
set status = 'PROCESSING', lease_owner = #{owner}, lease_token = #{token}, lease_until = #{leaseUntil},
    last_error_code = case when last_error_code = 'IN_APP_ATTEMPT_RESERVED' and #{inApp}
        then null else last_error_code end
where outbox_id = #{outboxId}
  and status in ('READY', 'PROCESSING')
  and available_at <= #{now}
  and (next_attempt_at is null or next_attempt_at <= #{now})
  and (lease_until is null or lease_until <= #{now})
